package com.gameaggregator.clientservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.clientservice.api.ClientDtos.*;import com.gameaggregator.clientservice.domain.*;import com.gameaggregator.clientservice.infrastructure.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class ClientService{final ClientOrganizationRepository orgs;final ClientApplicationRepository apps;final ClientEnvironmentRepository envs;final AllowlistEntryRepository allowlist;final ClientEntitlementRepository entitlements;public ClientService(ClientOrganizationRepository o,ClientApplicationRepository a,ClientEnvironmentRepository e,AllowlistEntryRepository w,ClientEntitlementRepository n){orgs=o;apps=a;envs=e;allowlist=w;entitlements=n;}public ClientOrganization organization(Organization r){return orgs.save(new ClientOrganization(r.tenantId(),r.slug(),r.name()));}public List<ClientOrganization> organizations(){return orgs.findAll();}public ClientOrganization organization(UUID id){return orgs.findById(id).orElseThrow(()->missing("CLIENT_ORGANIZATION_NOT_FOUND"));}public List<ClientApplication> applications(UUID organizationId){organization(organizationId);return apps.findAllByOrganizationId(organizationId);}public List<ClientEnvironment> environments(UUID applicationId){if(!apps.existsById(applicationId))throw missing("CLIENT_APPLICATION_NOT_FOUND");return envs.findAllByApplicationId(applicationId);}public List<AllowlistEntry> allowlist(UUID environmentId){if(!envs.existsById(environmentId))throw missing("CLIENT_ENVIRONMENT_NOT_FOUND");return allowlist.findAllByEnvironmentId(environmentId);}public List<ClientEntitlement> entitlements(UUID applicationId){if(!apps.existsById(applicationId))throw missing("CLIENT_APPLICATION_NOT_FOUND");return entitlements.findAllByApplicationId(applicationId);}public ClientApplication application(UUID id,Application r){if(!orgs.existsById(id))throw missing("CLIENT_ORGANIZATION_NOT_FOUND");return apps.save(new ClientApplication(id,r.name()));}public ClientEnvironment environment(UUID id,Environment r){if(!apps.existsById(id))throw missing("CLIENT_APPLICATION_NOT_FOUND");return envs.save(new ClientEnvironment(id,r.name()));}public AllowlistEntry allow(UUID id,Allowlist r){if(!envs.existsById(id))throw missing("CLIENT_ENVIRONMENT_NOT_FOUND");return allowlist.save(new AllowlistEntry(id,r.type(),r.value()));}public ClientApplication integration(UUID id,Integration r){var a=apps.findById(id).orElseThrow(()->missing("CLIENT_APPLICATION_NOT_FOUND"));a.integrationStatus=r.status();return a;}public ClientEntitlement entitlement(UUID id,Entitlement r){if(!apps.existsById(id))throw missing("CLIENT_APPLICATION_NOT_FOUND");return entitlements.save(new ClientEntitlement(id,r.gameId(),r.territory(),r.expiresAt()));}private NotFoundException missing(String code){return new NotFoundException(code,"Client resource was not found");}}
